SELECT b.CSNAME AS `美股名称`, b.COMB_SYMBOL AS `股票代码`, a.F044N AS `财年`, a.F001D AS `财政周期结束日期`, a.F005V AS `币种`, a.F003V AS `报表种类`, ROUND(a.F036N, 2) AS `经营净现金流(百万美元)`, ROUND(a.F008N, 2) AS `资本性支出(百万美元)`, ROUND(a.F036N - a.F008N, 2) AS `自由现金流(百万美元)` FROM VIEW_COM3104_CUM a JOIN AMERICAN_STOCK_MAIN b ON a.FIU_ID = b.FIU_ID WHERE b.COMB_SYMBOL = 'WMT.US' AND a.F044N IN (2024, 2025) AND a.F003V = 'FY' AND a.F036N IS NOT NULL AND a.F008N IS NOT NULL ORDER BY a.F044N ASC;
